    vbool4_t mask_f32v = __riscv_vmflt_vf_f32m8_b4(in_f32v, 0.0f, n);
    vfloat32m8_t out_f32v = __riscv_vfmul_vf_f32m8_mu(mask_f32v, in_f32v, in_f32v, slope, n);
    __riscv_vse32_v_f32m8(output, out_f32v, n); output += n;
