/* ======== prob 21 f32-f16-vcvt — sol ======== */
void sol_r23_test_rvv(
    size_t batch,
    const float* input,
    uint16_t* output,
    const void* params)
{
  assert(batch != 0);
  assert(batch % sizeof(float) == 0);
  assert(input != NULL);
  assert(output != NULL);

  size_t n = batch / sizeof(float);
  uint16_t* o = output;

  while (n > 0) {
    size_t vl = __riscv_vsetvl_e32m8(n);

    vfloat32m8_t vx = __riscv_vle32_v_f32m8(input, vl);

    vfloat32m8_t vabsx = __riscv_vfabs_v_f32m8(vx, vl);
    vuint32m8_t vabsx_u = __riscv_vreinterpret_v_f32m8_u32m8(vabsx);

    vuint32m8_t vbias = __riscv_vadd_vx_u32m8(vabsx_u, UINT32_C(0x07800000), vl);

    vfloat32m8_t vf = __riscv_vfmul_vf_f32m8(vabsx, 0x1.0p+112f, vl);
    vbool4_t vnanmask = __riscv_vmsgtu_vx_u32m8_b4(vabsx_u, UINT32_C(0x7F800000), vl);

    vbias = __riscv_vand_vx_u32m8(vbias, UINT32_C(0x7F800000), vl);
    vf = __riscv_vfmul_vf_f32m8(vf, 0x1.0p-110f, vl);

    vbias = __riscv_vmaxu_vx_u32m8(vbias, UINT32_C(0x40000000), vl);

    vf = __riscv_vfadd_vv_f32m8(vf, __riscv_vreinterpret_v_u32m8_f32m8(vbias), vl);

    vuint32m8_t vf_u = __riscv_vreinterpret_v_f32m8_u32m8(vf);
    vuint32m8_t vx_u = __riscv_vreinterpret_v_f32m8_u32m8(vx);

    vuint16m4_t vexph = __riscv_vnsrl_wx_u16m4(vf_u, 13, vl);
    vuint16m4_t vmanth = __riscv_vnsrl_wx_u16m4(vf_u, 0, vl);
    vuint16m4_t vsignh = __riscv_vnsrl_wx_u16m4(vx_u, 16, vl);

    vexph = __riscv_vand_vx_u16m4(vexph, UINT16_C(0x7C00), vl);
    vmanth = __riscv_vand_vx_u16m4(vmanth, UINT16_C(0x0FFF), vl);
    vsignh = __riscv_vand_vx_u16m4(vsignh, UINT16_C(0x8000), vl);

    vuint16m4_t vh = __riscv_vadd_vv_u16m4(vmanth, vexph, vl);

    vh = __riscv_vmerge_vxm_u16m4(vh, UINT16_C(0x7E00), vnanmask, vl);

    vh = __riscv_vor_vv_u16m4(vh, vsignh, vl);

    __riscv_vse16_v_u16m4(o, vh, vl);

    input += vl;
    o += vl;
    n -= vl;
  }
}
/* ======== prob 8 f32-vcmul — up ======== */
void up_r24_xnn_f32_vcmul_ukernel__rvv_u4v(
    size_t batch,
    const float* input_a,
    const float* input_b,
    float* output,
    const struct xnn_f32_default_params* restrict params)
{
  assert(batch != 0);
  assert(batch % sizeof(float) == 0);
  assert(input_a != NULL);
  assert(input_b != NULL);
  assert(output != NULL);

  batch >>= XNN_LOG2_SIZEOF_FLOAT;

  const float* ar = input_a;
  const float* ai = input_a + batch;
  const float* br = input_b;
  const float* bi = input_b + batch;
  float* or = output;
  float* oi = output + batch;

  for (; batch > 0; ) {
    size_t n = __riscv_vsetvl_e32m4(batch); batch -= n;
    vfloat32m4_t ar_f32v = __riscv_vle32_v_f32m4(ar, n); ar += n;
    vfloat32m4_t ai_f32v = __riscv_vle32_v_f32m4(ai, n); ai += n;
    vfloat32m4_t br_f32v = __riscv_vle32_v_f32m4(br, n); br += n;
    vfloat32m4_t bi_f32v = __riscv_vle32_v_f32m4(bi, n); bi += n;
    vfloat32m4_t ai_bi_f32v = __riscv_vfmul_vv_f32m4(ai_f32v, bi_f32v, n);
    vfloat32m4_t ai_br_f32v = __riscv_vfmul_vv_f32m4(ai_f32v, br_f32v, n);
    vfloat32m4_t ar_br_sub_ai_bi_f32v = __riscv_vfmsac_vv_f32m4(ai_bi_f32v, ar_f32v, br_f32v, n);
    vfloat32m4_t ar_bi_plus_ai_br_f32v = __riscv_vfmacc_vv_f32m4(ai_br_f32v, ar_f32v, bi_f32v, n);
    __riscv_vse32_v_f32m4(or, ar_br_sub_ai_bi_f32v, n); or += n;
    __riscv_vse32_v_f32m4(oi, ar_bi_plus_ai_br_f32v, n); oi += n;
  }
}
/* ======== prob 8 f32-vcmul — sol ======== */
void sol_r24_test_rvv(
    size_t batch,
    const float* input_a,
    const float* input_b,
    float* output,
    const struct xnn_f32_default_params* params) XNN_OOB_READS
{
  assert(batch != 0);
  assert(batch % sizeof(float) == 0);
  assert(input_a != NULL);
  assert(input_b != NULL);
  assert(output != NULL);

  const float* ar = input_a;
  const float* ai = (const float*) ((uintptr_t) input_a + batch);
  const float* br = input_b;
  const float* bi = (const float*) ((uintptr_t) input_b + batch);
  float* out_r = output;
  float* out_i = (float*) ((uintptr_t) output + batch);

  size_t n = batch / sizeof(float);
  while (n > 0) {
    size_t vl = __riscv_vsetvl_e32m4(n);

    vfloat32m4_t var = __riscv_vle32_v_f32m4(ar, vl);
    vfloat32m4_t vai = __riscv_vle32_v_f32m4(ai, vl);
    vfloat32m4_t vbr = __riscv_vle32_v_f32m4(br, vl);
    vfloat32m4_t vbi = __riscv_vle32_v_f32m4(bi, vl);

    vfloat32m4_t vaccr = __riscv_vfmul_vv_f32m4(var, vbr, vl);
    vfloat32m4_t vacci = __riscv_vfmul_vv_f32m4(var, vbi, vl);

    vfloat32m4_t temp_r = __riscv_vfmul_vv_f32m4(vai, vbi, vl);
    vaccr = __riscv_vfsub_vv_f32m4(vaccr, temp_r, vl);

    vfloat32m4_t temp_i = __riscv_vfmul_vv_f32m4(vai, vbr, vl);
    vacci = __riscv_vfadd_vv_f32m4(vacci, temp_i, vl);

    __riscv_vse32_v_f32m4(out_r, vaccr, vl);
    __riscv_vse32_v_f32m4(out_i, vacci, vl);

    ar += vl;
    ai += vl;
    br += vl;
    bi += vl;
    out_r += vl;
    out_i += vl;
    n -= vl;
  }
}
